  notificationDeliveries = pgTable("notification_deliveries", {
    id: uuid("id").primaryKey().defaultRandom(),
    notificationId: text("notification_id").notNull(),
    organizationId: text("organization_id").notNull(),
    projectId: uuid("project_id"),
    userId: text("user_id"),
    notificationType: notificationType("notification_type").notNull(),
    channel: notificationChannel("channel").notNull(),
    destinationKey: text("destination_key"),
    outcome: text("outcome", {
      enum: ["authorized", "delivered", "suppressed", "failed"]
    }),
    deliveryState: text("delivery_state", {
      enum: [
        "pending",
        "processing",
        "delivered",
        "failed",
        "suppressed",
        "uncertain"
      ]
    }),
    leaseOwner: text("lease_owner"),
    leaseExpiresAt: timestamp("lease_expires_at", { withTimezone: true }),
    requestStartedAt: timestamp("request_started_at", { withTimezone: true }),
    providerIdempotencyKey: text("provider_idempotency_key"),
    providerRef: text("provider_ref"),
    deliveredAt: timestamp("delivered_at", { withTimezone: true }),
    suppressedBy: uuid("suppressed_by").references(() => projectNotificationDeliveryRules.id, { onDelete: "set null" }),
    sourceComponentId: uuid("source_component_id"),
    effectiveComponentId: uuid("effective_component_id"),
    triggerEventId: text("trigger_event_id"),
    authorizedAt: timestamp("authorized_at", { withTimezone: true }),
    componentRegistryRevision: bigint2("component_registry_revision", {
      mode: "number"
    }),
    systemSuppressionReason: notificationSystemSuppressionReason("system_suppression_reason"),
    suppressedByComponentOperationId: uuid("suppressed_by_component_operation_id"),
    attempts: integer("attempts").notNull().default(0),
    error: text("error"),
    substrateRef: text("substrate_ref"),
    metadata: jsonb("metadata"),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull()
  }, (table3) => ({
    uniqueTarget: uniqueIndex("notification_deliveries_tenant_target_idx").on(table3.organizationId, table3.projectId, table3.notificationId, table3.notificationType, table3.channel, table3.destinationKey, table3.userId),
    orgCreatedIdx: index("notification_deliveries_org_created_idx").on(table3.organizationId, table3.createdAt),
    userCreatedIdx: index("notification_deliveries_user_created_idx").on(table3.userId, table3.createdAt).where(sql`${table3.userId} IS NOT NULL`),
    projectTypeIdx: index("notification_deliveries_project_type_idx").on(table3.projectId, table3.notificationType, table3.createdAt),
    sourceComponentProjectOrgFk: foreignKey({
      columns: [table3.sourceComponentId, table3.projectId, table3.organizationId],
      foreignColumns: [
        components.id,
        components.projectId,
        components.organizationId
      ],
      name: "notification_deliveries_source_component_project_org_fk"
    }),
    effectiveComponentProjectOrgFk: foreignKey({
      columns: [
        table3.effectiveComponentId,
        table3.projectId,
        table3.organizationId
      ],
      foreignColumns: [
        components.id,
        components.projectId,
        components.organizationId
      ],
      name: "notification_deliveries_effective_component_project_org_fk"
    }),
    suppressedOperationProjectOrgFk: foreignKey({
      columns: [
        table3.suppressedByComponentOperationId,
        table3.projectId,
        table3.organizationId
      ],
      foreignColumns: [
        componentRegistryOperations.id,
        componentRegistryOperations.projectId,
        componentRegistryOperations.organizationId
      ],
      name: "notification_deliveries_suppressed_operation_project_org_fk"
    }),
    suppressedRuleProjectOrgFk: foreignKey({
      columns: [table3.suppressedBy, table3.projectId, table3.organizationId],
      foreignColumns: [
        projectNotificationDeliveryRules.id,
        projectNotificationDeliveryRules.projectId,
        projectNotificationDeliveryRules.organizationId
      ],
      name: "notification_deliveries_suppressed_rule_project_org_fk"
    }),
    projectOrgFk: foreignKey({
      columns: [table3.projectId, table3.organizationId],
      foreignColumns: [projects.id, projects.organizationId],
      name: "notification_deliveries_project_org_fk"
    }),
    componentAttributionChk: check("notification_deliveries_component_attribution_chk", sql`(
        ${table3.sourceComponentId} IS NULL
        AND ${table3.effectiveComponentId} IS NULL
        AND ${table3.triggerEventId} IS NULL
        AND ${table3.componentRegistryRevision} IS NULL
        AND ${table3.authorizedAt} IS NULL
        AND (${table3.outcome} IS NULL OR ${table3.outcome} <> 'authorized')
        AND (
          (${table3.systemSuppressionReason} IS NULL)
          OR (${table3.outcome} = 'suppressed'
            AND ${table3.systemSuppressionReason} IN ('email_suppressed', 'access_revoked'))
        )
        AND ${table3.suppressedByComponentOperationId} IS NULL
      ) OR (
        ${table3.projectId} IS NOT NULL
        AND ${table3.sourceComponentId} IS NOT NULL
        AND ${table3.effectiveComponentId} IS NOT NULL
        AND ${table3.triggerEventId} IS NOT NULL
        AND ${table3.componentRegistryRevision} IS NOT NULL
        AND (
          (${table3.outcome} IN ('authorized', 'delivered', 'failed')
            AND ${table3.authorizedAt} IS NOT NULL
            AND ${table3.systemSuppressionReason} IS NULL)
          OR (${table3.outcome} = 'suppressed'
            AND ${table3.authorizedAt} IS NULL
            AND (${table3.suppressedBy} IS NOT NULL
              OR ${table3.systemSuppressionReason} IS NOT NULL))
          OR (${table3.outcome} = 'suppressed'
            AND ${table3.authorizedAt} IS NOT NULL
            AND ${table3.systemSuppressionReason} IN ('email_suppressed', 'access_revoked'))
        )
      )`),
    ledgerLifecycleChk: check("notification_deliveries_ledger_lifecycle_chk", sql`${table3.deliveryState} IS NULL OR (
        (${table3.deliveryState} = 'pending'
          AND ${table3.leaseOwner} IS NULL
          AND ${table3.leaseExpiresAt} IS NULL
          AND ${table3.requestStartedAt} IS NULL
          AND ${table3.deliveredAt} IS NULL)
        OR (${table3.deliveryState} = 'processing'
          AND ${table3.leaseOwner} IS NOT NULL
          AND ${table3.leaseExpiresAt} IS NOT NULL
          AND ${table3.deliveredAt} IS NULL)
        OR (${table3.deliveryState} IN ('delivered', 'failed', 'suppressed', 'uncertain')
          AND ${table3.leaseOwner} IS NULL
          AND ${table3.leaseExpiresAt} IS NULL
          AND (${table3.deliveryState} <> 'delivered' OR ${table3.deliveredAt} IS NOT NULL))
      )`),
    systemSuppressionChk: check("notification_deliveries_system_suppression_chk", sql`(
        ${table3.systemSuppressionReason} IS NULL
        AND ${table3.suppressedByComponentOperationId} IS NULL
      ) OR (
        ${table3.outcome} = 'suppressed'
        AND ${table3.systemSuppressionReason} IN ('component_retired', 'component_inactive')
        AND ${table3.suppressedByComponentOperationId} IS NOT NULL
        AND ${table3.authorizedAt} IS NULL
      ) OR (
        ${table3.outcome} = 'suppressed'
        AND ${table3.systemSuppressionReason} IN ('email_suppressed', 'access_revoked')
        AND ${table3.suppressedByComponentOperationId} IS NULL
      ) OR (
        -- A severity rule declines to page BEFORE the provider is contacted,
        -- so it may only suppress a delivery that was never authorized. This
        -- branch deliberately requires authorized_at IS NULL, unlike the
        -- email_suppressed/access_revoked branch above, which covers facts
        -- only learnable after an authorized delivery was attempted.
        ${table3.outcome} = 'suppressed'
        AND ${table3.systemSuppressionReason} = 'severity_rule_skip'
        AND ${table3.suppressedByComponentOperationId} IS NULL
        AND ${table3.authorizedAt} IS NULL
      )`)
  }));
