    maxRunsPositiveChk: check("automations_max_runs_positive_chk", sql`${table3.maxRuns} IS NULL OR ${table3.maxRuns} >= 1`),
    triggerSignalConsistencyChk: check("automations_trigger_signal_consistency_chk", sql`(
        (
          ${table3.triggerType} = 'cron'
          AND ${table3.signalType} IS NULL
          AND ${table3.signalDefinitionId} IS NULL
          AND (
            (${table3.scriptPath} IS NOT NULL AND ${table3.scriptId} IS NULL)
            OR (${table3.scriptPath} IS NULL AND ${table3.scriptId} IS NOT NULL)
          )
          AND ${table3.cronExpression} IS NOT NULL
        ) OR (
          ${table3.triggerType} = 'signal'
          AND ${table3.signalType} IS NOT NULL
          AND ${table3.signalType} <> 'expression_matched'
          AND ${table3.signalDefinitionId} IS NULL
          AND ${table3.scriptPath} IS NULL
          AND ${table3.scriptId} IS NULL
          AND ${table3.cronExpression} IS NULL
        ) OR (
          ${table3.triggerType} = 'signal'
          AND ${table3.signalType} = 'expression_matched'
          AND ${table3.signalDefinitionId} IS NOT NULL
          AND ${table3.scriptPath} IS NULL
          AND ${table3.scriptId} IS NULL
          AND ${table3.cronExpression} IS NULL
        )
      )`),
