import { z as z8 } from "zod";

// ../../contracts/public-api/src/connection-status.ts
import { z as z7 } from "zod";
var ConnectionStatusSchema = z7.object({
  state: z7.enum([
    "connected",
    "needs_attention",
    "connecting",
    "not_connected"
  ]),
  reasonCode: z7.enum([
    "credentials_rejected",
    "permissions_missing",
    "configuration_invalid",
    "discovery_failed",
    "health_check_failed",
    "stream_failed",
    "recovery_required"
  ]).nullable(),
  checkedAt: z7.string().datetime().nullable(),
  verification: z7.enum(["verified", "unverified"])
});
var ConnectionResourceKindSchema = z7.enum([
  "integration",
  "connected_account",
  "mcp_connector",
  "log_source",
  "sandbox_cli"
]);
var ConnectionScopeSchema = z7.object({
  kind: z7.enum(["user", "organization", "project"]),
  id: z7.string()
});
var ConnectionRemediationTargetSchema = z7.object({
  kind: ConnectionResourceKindSchema,
  resourceId: z7.string(),
  providerId: z7.string(),
  scope: ConnectionScopeSchema
});
var ConnectionRecoverySchema = z7.object({
  action: z7.enum([
    "reconnect",
    "update_credentials",
    "manage_installation",
    "manage_owner",
    "review_setup"
  ]).nullable(),
  canCheck: z7.boolean(),
  canDisconnect: z7.boolean(),
  target: ConnectionRemediationTargetSchema.optional()
});
var ConnectionAttentionItemSchema = ConnectionRemediationTargetSchema.extend({
  id: z7.string(),
  displayName: z7.string(),
  status: ConnectionStatusSchema,
  remediationTarget: ConnectionRemediationTargetSchema
});
var ConnectionAttentionSummarySchema = z7.object({
  items: z7.array(ConnectionAttentionItemSchema),
  total: z7.number().int().nonnegative(),
  coverage: z7.array(z7.object({
    kind: ConnectionResourceKindSchema,
    scope: ConnectionScopeSchema.nullable(),
    state: z7.enum(["complete", "unavailable", "not_applicable"]),
    canRetainPrevious: z7.boolean()
  })),
  evaluatedAt: z7.string().datetime()
});

